+    private static boolean isNamedGroupSupported(String namedGroup, String[] supportedNamedGroups) {
+        for (String supportedNamedGroup : supportedNamedGroups) {
+            if (namedGroup.trim().equalsIgnoreCase(supportedNamedGroup)) {
+                return true;
+            }
+        }
+        return false;
+    }
